import test from 'node:test';import assert from 'node:assert/strict';import{createAcodeHost,LocalRemounter}from'../src/index.mjs';
test('Acode terminal executes local non-JavaScript and heavy faculties without a backend',async()=>{const calls=[];const host=createAcodeHost({terminal:async input=>{calls.push(input);return{exitCode:0,stdout:'ok'};}});const run=await host.execute(['python','process'],{command:'python3 tool.py'});assert.equal(run.facultyId,'acode.terminal');assert.equal(calls.length,1);});
test('pure JavaScript stays in the portable runtime',async()=>{const host=createAcodeHost();const run=await host.execute(['javascript','pure'],()=>42);assert.equal(run.facultyId,'acode.javascript');assert.equal(run.result,42);});
test('backend donor boundaries remount to local Acode faculties',()=>{const host=createAcodeHost({terminal:async()=>{},storage:async()=>{},views:async()=>{}});const plan=new LocalRemounter(host).plan({id:'donor',boundaries:[{kind:'express'},{kind:'supabase'},{kind:'python-service'},{kind:'remote-ui'}]});assert.equal(plan.backendRequired,false);assert.deepEqual(plan.replacements.map(x=>x.replacement),['local-channel','local-persistence','terminal-process','local-view']);});
